<script setup lang="ts">
import { Truck } from '@lucide/vue';
const form=defineModel<{enabled:boolean;fixed_amount:number}>({required:true});
defineProps<{loading?:boolean;saving?:boolean;error?:boolean}>();
const emit=defineEmits<{save:[];retry:[]}>();
const valid=computed(()=>Number.isFinite(Number(form.value.fixed_amount))&&Number(form.value.fixed_amount)>=0&&Number(form.value.fixed_amount)<=9999.99&&Math.abs(Number(form.value.fixed_amount)*100-Math.round(Number(form.value.fixed_amount)*100))<.00001);
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
</script>
<template><section class="max-w-3xl rounded-2xl border border-[#e1e6ee] bg-white p-6 md:p-8"><header class="mb-6 flex items-center gap-3"><Truck class="text-it-primary" :size="26"/><h2 class="m-0 text-xl font-semibold text-[#172b4d]">Configuração de entrega</h2></header><div v-if="error" role="alert" class="rounded-xl border border-red-200 bg-red-50 p-4 text-red-800">Não foi possível carregar a configuração. <button @click="emit('retry')" class="font-semibold underline">Tentar novamente</button></div><form v-else @submit.prevent="valid && emit('save')" class="space-y-6"><fieldset :disabled="loading||saving" class="space-y-6"><label class="flex cursor-pointer items-center gap-3 rounded-xl border border-[#dce2ff] bg-[#f5f6ff] p-4"><input type="checkbox" v-model="form.enabled" class="h-5 w-5 accent-[#2820d9]"/><span><strong class="block text-[#172b4d]">Habilitar cobrança de frete</strong><span class="text-sm text-[#52667f]">{{form.enabled?'Entrega em casa terá o valor definido abaixo.':'Desativado: nenhuma cobrança de frete nas compras.'}}</span></span></label><div class="max-w-sm"><label for="fixed_shipping" class="mb-2 block font-semibold text-[#172b4d]">Valor fixo por pedido (R$)</label><input id="fixed_shipping" type="number" inputmode="decimal" min="0" max="9999.99" step="0.01" v-model.number="form.fixed_amount" required class="w-full rounded-xl border border-[#ccd5e5] bg-white px-4 py-3 text-lg text-[#172b4d]"/><p class="mt-2 text-sm text-[#52667f]">É cobrado uma vez por pedido, mesmo com vários veículos. O valor pode ficar salvo enquanto o frete estiver desativado.</p><p v-if="!valid" class="mt-2 text-sm text-red-700">Informe um valor de 0 a 9.999,99, com até duas casas decimais.</p></div><div class="rounded-xl border border-[#e1e6ee] p-4 text-sm text-[#52667f]"><p>Entrega em casa: <strong>{{ money(form.enabled?Number(form.fixed_amount||0):0) }}</strong></p><p class="mt-1">Retirada em PDV: <strong>Grátis</strong></p><p class="mt-2">Cupons de desconto dos kits não alteram o valor do frete.</p></div></fieldset><button type="submit" :disabled="loading||saving||!valid" class="rounded-xl bg-it-primary px-6 py-3 font-semibold text-white disabled:opacity-40">{{saving?'Salvando...':loading?'Carregando...':'Salvar configuração'}}</button></form></section></template>
